mapper.update:
UPDATE benchmark
SET name = #{request.name},
    description = #{request.description},
    status = #{request.status}
    WHERE id = #{id} 
      AND owner_id = #{userId}

mapper.delete:
UPDATE benchmark
SET status = 'ARCHIVED'
WHERE id = #{id} 
  AND owner_id = #{userId}

mapper.select:
SELECT
    id,owner_id,name,description,status,created_at,updated_at,category
    FROM benchmark
    WHERE owner_id = #{userId}
    ORDER BY created_at DESC,id DESC
    LIMIT #{size} OFFSET #{offset}
